        expect(font.glyphNames.names.length).toBe(font.numGlyphs);
        expect(font.glyphNames.names[4]).toBe('A');
    });

    test('parses hinting tables into the font tables collection', () => {
        const font = parse(readFont('Changa-Regular.ttf'));

        expect(Array.isArray(font.tables.cvt)).toBe(true);
        expect(font.tables.cvt.length).toBe(77);
        expect(Array.isArray(font.tables.fpgm)).toBe(true);
        expect(font.tables.fpgm.length).toBe(3335);
        expect(Array.isArray(font.tables.prep)).toBe(true);
        expect(font.tables.prep.length).toBe(177);
        expect(font.tables.gasp.gaspRanges).toHaveLength(1);
        expect(font.tables.gasp.gaspRanges[0].rangeMaxPPEM).toBe(65535);
    });

    test('initializes GPOS based positioning and layout tables', () => {
        const font = parse(readFont('Changa-Regular.ttf'));

        expect(font.tables.gpos).toBeDefined();
