        const font = parse(readFont('Changa-Regular.ttf'));

        expect(font.tables.kern).toBeUndefined();
        expect(font.kerningPairs).toEqual({});
    });

    test('always attaches a palette manager to the parsed font', () => {
        const font = parse(readFont('Changa-Regular.ttf'));

        expect(font.palettes).toBeDefined();
        expect(font.palettes.font).toBe(font);
        expect(font.palettes.cpal()).toBe(false);
