describe('deltaInterpolate', () => {
    test('interpolates deltas between two reference points', () => {
        const processor = new VariationProcessor({});
        const glyphPoints = [point(0, 0), point(50, 50), point(100, 100)];
        const points = [point(0, 0), point(50, 50), point(110, 100)];
        processor.deltaInterpolate(1, 1, 0, 2, glyphPoints, points);
        expect(points[1].x).toBeCloseTo(55, 6);
        expect(points[1].y).toBeCloseTo(50, 6);
        expect(points[0]).toEqual(point(0, 0));
        expect(points[2]).toEqual(point(110, 100));
    });

    test('returns without touching points when the range is empty', () => {
        const processor = new VariationProcessor({});
        const glyphPoints = [point(0, 0), point(10, 10)];
        const points = [point(0, 0), point(10, 10)];
        processor.deltaInterpolate(2, 1, 0, 1, glyphPoints, points);
        expect(points).toEqual([point(0, 0), point(10, 10)]);
    });

    test('correctly interpolates when reference points are supplied in reverse order', () => {
        const processor = new VariationProcessor({});
        const glyphPoints = [point(100, 100), point(50, 50), point(0, 0)];
        const points = [point(110, 100), point(50, 50), point(0, 0)];
        processor.deltaInterpolate(1, 1, 0, 2, glyphPoints, points);
        expect(points[1].x).toBeCloseTo(55, 6);
    });

    test('scales the deltas in each axis independently', () => {
        const processor = new VariationProcessor({});
        const glyphPoints = [point(0, 0), point(50, 25), point(100, 100)];
        const points = [point(0, 0), point(50, 25), point(100, 110)];
        processor.deltaInterpolate(1, 1, 0, 2, glyphPoints, points);
        expect(points[1].x).toBeCloseTo(50, 6);
        expect(points[1].y).toBeCloseTo(27.5, 6);
        expect(points[1].onCurve).toBe(true);
        expect(points[1].lastPointOfContour).toBe(false);
    });
});

describe('interpolatePoints', () => {
