describe('applyTupleVariationStore (gvar)', () => {
    const axes = [axis('wght', 0, 0, 1)];
    const basePoints = [point(0, 0), point(50, 0), point(100, 0, true, true)];

    test('defaults to the font variation coordinates', () => {
        const font = makeFont({
            axes,
            coords: { wght: 0.5 },
            gvar: { sharedTuples: [], glyphVariations: {} },
        });
        const processor = new VariationProcessor(font);
        const variationData = {
            headers: [{ peakTuple: [1], privatePoints: [], deltas: [10, 10, 10], deltasY: [0, 0, 0] }],
            sharedPoints: [],
        };
        const result = processor.applyTupleVariationStore(variationData, basePoints);
        expect(result.map((p) => p.x)).toEqual([5, 55, 105]);
    });

    test('applies deltas to every point when no point subset is specified', () => {
        const processor = new VariationProcessor(makeFont({ axes }));
        const variationData = {
            headers: [{ peakTuple: [1], privatePoints: [], deltas: [10, 20, 30], deltasY: [-1, -2, -3] }],
            sharedPoints: [],
        };
        const result = processor.applyTupleVariationStore(variationData, basePoints, { wght: 0.5 });
        expect(result).toEqual([
            point(5, -1), point(60, -1), point(115, -2, true, true),
        ]);
        expect(basePoints).toEqual([point(0, 0), point(50, 0), point(100, 0, true, true)]);
    });

    test('uses shared tuple records when the header has no embedded peak tuple', () => {
        const processor = new VariationProcessor(makeFont({
            axes,
            gvar: { sharedTuples: [[1]], glyphVariations: {} },
        }));
        const variationData = {
            headers: [{ sharedTupleRecordsIndex: 0, privatePoints: [], deltas: [8, 8, 8], deltasY: [0, 0, 0] }],
            sharedPoints: [],
        };
        const result = processor.applyTupleVariationStore(variationData, basePoints, { wght: 0.5 });
        expect(result.map((p) => p.x)).toEqual([4, 54, 104]);
    });

    test('ignores axes whose peak coordinate is zero', () => {
        const processor = new VariationProcessor(makeFont({ axes }));
        const variationData = {
            headers: [{ peakTuple: [0], privatePoints: [], deltas: [10, 10, 10], deltasY: [0, 0, 0] }],
            sharedPoints: [],
        };
        const result = processor.applyTupleVariationStore(variationData, basePoints, { wght: 1 });
        expect(result.map((p) => p.x)).toEqual([10, 60, 110]);
    });

    test('skips a tuple when normalized coordinates are zero', () => {
        const processor = new VariationProcessor(makeFont({ axes }));
        const variationData = {
            headers: [{ peakTuple: [1], privatePoints: [], deltas: [10, 10, 10], deltasY: [0, 0, 0] }],
            sharedPoints: [],
        };
        expect(processor.applyTupleVariationStore(variationData, basePoints, { wght: 0 }).map((p) => p.x))
            .toEqual([0, 50, 100]);
    });

    test('skips a tuple when coordinates fall outside the tuple range', () => {
        const processor = new VariationProcessor(makeFont({ axes }));
        const variationData = {
            headers: [{ peakTuple: [1], privatePoints: [], deltas: [10, 10, 10], deltasY: [0, 0, 0] }],
            sharedPoints: [],
        };
        expect(processor.applyTupleVariationStore(variationData, basePoints, { wght: -1 }).map((p) => p.x))
            .toEqual([0, 50, 100]);
    });

    test('supports intermediate start and end tuples', () => {
        const processor = new VariationProcessor(makeFont({ axes }));
        const variationData = {
            headers: [{
                peakTuple: [1],
                intermediateStartTuple: [0.5],
                intermediateEndTuple: [1],
                privatePoints: [],
                deltas: [10, 10, 10],
                deltasY: [0, 0, 0],
            }],
            sharedPoints: [],
        };
        expect(processor.applyTupleVariationStore(variationData, basePoints, { wght: 0.25 }).map((p) => p.x))
            .toEqual([0, 50, 100]);
        expect(processor.applyTupleVariationStore(variationData, basePoints, { wght: 0.75 }).map((p) => p.x))
            .toEqual([5, 55, 105]);
        expect(processor.applyTupleVariationStore(variationData, basePoints, { wght: 1 }).map((p) => p.x))
            .toEqual([10, 60, 110]);
    });

    test('interpolates private point deltas and rounds the result', () => {
        const processor = new VariationProcessor(makeFont({ axes }));
        const variationData = {
            headers: [{ peakTuple: [1], privatePoints: [0, 2], deltas: [0, 10], deltasY: [0, 0] }],
            sharedPoints: [],
        };
        const result = processor.applyTupleVariationStore(variationData, basePoints, { wght: 0.5 });
        expect(result.map((p) => p.x)).toEqual([0, 53, 105]);
        expect(result.every((p) => Number.isInteger(p.x))).toBe(true);
    });

    test('uses shared points when private points are absent', () => {
        const processor = new VariationProcessor(makeFont({ axes }));
        const variationData = {
            headers: [{ peakTuple: [1], privatePoints: [], deltas: [30], deltasY: [0] }],
            sharedPoints: [1],
        };
        const result = processor.applyTupleVariationStore(variationData, basePoints, { wght: 0.5 });
        expect(result.map((p) => p.x)).toEqual([15, 65, 115]);
    });

    test('ignores point indices beyond the available points', () => {
        const processor = new VariationProcessor(makeFont({ axes }));
        const variationData = {
            headers: [{ peakTuple: [1], privatePoints: [1, 99], deltas: [10, 50], deltasY: [0, 0] }],
            sharedPoints: [],
        };
        const result = processor.applyTupleVariationStore(variationData, basePoints, { wght: 0.5 });
        expect(result.map((p) => p.x)).toEqual([5, 55, 105]);
    });

    test('applies multiple tuple headers cumulatively', () => {
        const processor = new VariationProcessor(makeFont({ axes }));
        const variationData = {
            headers: [
                { peakTuple: [1], privatePoints: [], deltas: [10, 10, 10], deltasY: [0, 0, 0] },
                { peakTuple: [1], privatePoints: [], deltas: [20, 20, 20], deltasY: [0, 0, 0] },
            ],
            sharedPoints: [],
        };
        expect(processor.applyTupleVariationStore(variationData, basePoints, { wght: 0.5 }).map((p) => p.x))
            .toEqual([15, 65, 115]);
    });

    test('delegates composite glyphs to component transformation', () => {
        const firstComponentGlyph = { index: 0, points: [point(10, 10), point(20, 20)] };
        const secondComponentGlyph = { index: 1, points: [point(10, 10), point(20, 20)] };
        const font = makeFont({ axes, glyphs: { 0: firstComponentGlyph, 1: secondComponentGlyph } });
        const processor = new VariationProcessor(font);
        const glyph = {
            index: 5,
            isComposite: true,
            points: [point(0, 0), point(0, 0), point(0, 0), point(0, 0)],
            components: [
                { glyphIndex: 0, xScale: 1, scale01: 0, scale10: 0, yScale: 1, dx: 0, dy: 0 },
                { glyphIndex: 1, xScale: 1, scale01: 0, scale10: 0, yScale: 1, dx: 100, dy: 200 },
            ],
        };
        const variationData = {
            headers: [{ peakTuple: [1], privatePoints: [1], deltas: [10], deltasY: [20] }],
            sharedPoints: [],
        };
        const result = processor.applyTupleVariationStore(variationData, glyph.points, { wght: 0.5 }, 'gvar', { glyph });
        expect(result).toEqual([
            point(10, 10), point(20, 20), point(115, 220), point(125, 230),
        ]);
        expect(glyph.components[1].dx).toBe(100);
        expect(glyph.components[1].dy).toBe(200);
    });
});

